/**
 * The closed discriminated union on `kind` of what a device is permitted to send. `received_at` is
 * absent from every member: a device-supplied receive time would be neither of the two clocks the
 * contract allows.
 */
export type DeviceSubmission =
  | DevicePromptM0
  | DevicePromptM1
  | DevicePromptM2
  | DevicePromptM3
  | DeviceUsageRollup
  | DeviceModelDetection;

/**
 * The closed discriminated union on `kind` of the envelope as stored, which is the device
 * submission plus the server-assigned `received_at`.
 */
export type StoredEnvelope =
  | StoredPromptM0
  | StoredPromptM1
  | StoredPromptM2
  | StoredPromptM3
  | StoredUsageRollup
  | StoredModelDetection;
